// @ts-nocheck
// supabase/functions/og-card/index.ts  v6
// - Embedded Noto Sans SC (CJK support) via base64
// - Fixed layout coordinates
// - Better cover image handling
import { createClient } from '@supabase/supabase-js';
import { initWasm, Resvg } from 'npm:@resvg/resvg-wasm';

const CORS = {
    'Access-Control-Allow-Origin':  '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

let wasmReady = false;
let fontBuffers: Uint8Array[] = [];

async function init() {
    if (wasmReady) return;
    await initWasm(fetch('https://unpkg.com/@resvg/resvg-wasm@2.6.2/index_bg.wasm'));
    function b64ToBytes(s) {
        const bin = atob(s); const b = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) b[i] = bin.charCodeAt(i); return b;
    }
    fontBuffers = [b64ToBytes(""), b64ToBytes("")];
    console.log('Fonts loaded: latin=' + fontBuffers[0].byteLength + ' cjk=' + fontBuffers[1].byteLength);
    wasmReady = true;
}

function toSlugSimple(title) {
    if (!title) return 'book';
    return title
        .replace(/[\u3000-\u9fff\uac00-\ud7af\uf900-\ufaff]/g,' ')
        .replace(/[：:·•—–()\[\]《》「」『』【】]/g,' ')
        .replace(/[^a-zA-Z0-9\s-]/g,' ')
        .toLowerCase().replace(/\s+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').trim()||'book';
}

function esc(s)    {
    // Only escape HTML-unsafe ASCII chars — never touch multibyte UTF-8 sequences
    return String(s||'').replace(/[&"<>]/g, c => ({'&':'&amp;','"':'&quot;','<':'&lt;','>':'&gt;'}[c]));
}
// Convert all non-ASCII chars to HTML numeric entities — guarantees correct display regardless of charset
function htmlEnt(s) {
    return String(s||'').replace(/[&"<>]/g, c => ({'&':'&amp;','"':'&quot;','<':'&lt;','>':'&gt;'}[c]))
        .replace(/[^\x00-\x7F]/g, c => `&#${c.codePointAt(0)};`);
}
function escSvg(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;'); }

function svgWrap(text, x, maxChars, maxLines, lineH) {
    const tokens = text.match(/[\u3000-\u9fff\uac00-\ud7af]|[^\u3000-\u9fff\uac00-\ud7af\s]+|\s+/g)||[];
    const lines=[]; let line='';
    for (const t of tokens) {
        if ((line+t).trimEnd().length > maxChars && line.trim()) {
            lines.push(line.trim()); line=t.trim();
            if (lines.length >= maxLines-1){ line+='…'; break; }
        } else { line+=t; }
    }
    if (line.trim()) lines.push(line.trim());
    return lines.slice(0,maxLines).map((l,i)=>
        `<tspan x="${x}" dy="${i===0?0:lineH}">${escSvg(l)}</tspan>`
    ).join('');
}

function starsSvg(rating, x, y) {
    const r=Math.min(5,Math.max(1,Math.round(rating)));
    return Array.from({length:5},(_,i)=>
        `<text x="${x+i*34}" y="${y}" font-size="28" font-family="sans-serif" fill="${i<r?'#ff0000':'#dddddd'}">${i<r?'★':'☆'}</text>`
    ).join('');
}

function buildSvg(review, book, coverDataUrl) {
    const F = 'sans-serif';
    // Fixed layout — right panel starts at x=420
    const RX = 450;  // right panel content left edge
    const RW = 700;  // usable width

    // Use English subtitle if available (after colon), otherwise use full title
    // This avoids CJK font rendering issues
    const rawTitle = book?.title || 'Book Review';
    const colonIdx = rawTitle.search(/[：:]/);
    const titleText = colonIdx > 0
        ? rawTitle.substring(colonIdx + 1).trim()  // "From the Arctic to the Antarctic"
        : rawTitle;                                  // fallback: full title
    // Strip CJK chars from author since we only have Latin font
    const rawAuthor = book?.author || '';
    const authorText = `by ${rawAuthor.replace(/[　-鿿가-힯豈-﫿]/g, '').trim()}`;
    const excerptText = `"${(review.text||'').replace(/\s+/g,' ').substring(0,180)}${(review.text||'').length>180?'…':''}"`;
    const dateText    = new Date(review.timestamp).toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric'});
    const initial     = (review.username||'?').charAt(0).toUpperCase();

    const titleWrap   = svgWrap(titleText,  RX, 38, 2, 44);
    const titleLines  = (titleWrap.match(/<tspan/g)||[]).length;
    const excerptWrap = svgWrap(excerptText, RX+12, 34, 4, 32);

    const titleY   = 140;
    const authorY  = titleY + titleLines * 44 + 12;
    const starsY   = authorY + 40;
    const accentY  = starsY + (review.rating ? 48 : 16);
    const excerptY = accentY + 20;
    const avatarCY = 572;

    return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1200" height="630" viewBox="0 0 1200 630">
<!-- Background -->
<rect width="1200" height="630" fill="#ffffff"/>
<!-- Left: dark bg (cover will be composited onto this after SVG render) -->
<rect x="0" y="0" width="400" height="630" fill="#140000"/>
<!-- Red divider -->
<rect x="400" y="0" width="4" height="630" fill="#ff0000"/>
<!-- White right panel bg -->
<rect x="404" y="0" width="796" height="630" fill="#ffffff"/>
<!-- Top bar: logo + badge -->
<rect x="450" y="28" width="38" height="38" rx="5" fill="#ff0000"/>
<text x="469" y="52" font-size="18" font-family="${F}" fill="#ffffff" text-anchor="middle" font-weight="bold">A</text>
<text x="500" y="52" font-size="16" font-family="${F}" fill="#1a1a1a" font-weight="bold">ACER BOOKS</text>
<rect x="960" y="26" width="200" height="34" rx="5" fill="#ff0000"/>
<text x="1060" y="48" font-size="13" font-family="${F}" fill="#ffffff" text-anchor="middle" font-weight="bold">READER REVIEW</text>
<!-- Separator -->
<line x1="450" y1="82" x2="1160" y2="82" stroke="#e8e8e8" stroke-width="1.5"/>
<!-- Book title -->
<text x="${RX}" y="${titleY}" font-size="30" font-family="${F}" fill="#1a1a1a" font-weight="bold">${titleWrap}</text>
<!-- Author -->
<text x="${RX}" y="${authorY}" font-size="17" font-family="${F}" fill="#888888" font-style="italic">${escSvg(authorText)}</text>
<!-- Stars -->
${review.rating ? starsSvg(review.rating, RX, starsY) : ''}
<!-- Red accent -->
<rect x="${RX}" y="${accentY}" width="5" height="${excerptText.length > 100 ? 100 : 60}" fill="#ff0000"/>
<!-- Excerpt -->
<text x="${RX+16}" y="${excerptY}" font-size="18" font-family="${F}" fill="#444444" font-style="italic">${excerptWrap}</text>
<!-- Reviewer -->
<circle cx="${RX+20}" cy="${avatarCY}" r="22" fill="#ff0000"/>
<text x="${RX+20}" y="${avatarCY+7}" font-size="17" font-family="${F}" fill="#ffffff" text-anchor="middle" font-weight="bold">${escSvg(initial)}</text>
<text x="${RX+54}" y="${avatarCY-6}" font-size="15" font-family="${F}" fill="#1a1a1a" font-weight="bold">${escSvg(review.username||'')}</text>
<text x="${RX+54}" y="${avatarCY+14}" font-size="13" font-family="${F}" fill="#888888">${escSvg(dateText)}</text>
<!-- Footer brand -->
<text x="1160" y="618" font-size="15" font-family="${F}" fill="#ff0000" text-anchor="end" font-weight="bold">acerbooks.ca</text>
</svg>`;
}

Deno.serve(async (req) => {
    if (req.method==='OPTIONS') return new Response('ok',{headers:CORS});
    try {
        const SUPABASE_URL     = Deno.env.get('SUPABASE_URL');
        const SERVICE_ROLE_KEY = Deno.env.get('SERVICE_ROLE_KEY');
        const SITE             = 'https://acerbooks.ca';
        const url  = new URL(req.url);
        const rid  = url.searchParams.get('rid')?.trim();
        const mode = url.searchParams.get('mode');
        if (!rid) return new Response('Missing rid',{status:400,headers:CORS});

        const sb = createClient(SUPABASE_URL, SERVICE_ROLE_KEY);
        const {data:review} = await sb.from('reviews')
            .select('id,book_id,username,text,rating,timestamp').eq('id',rid).maybeSingle();
        if (!review) return new Response(`<html><body><a href="${SITE}">Home</a></body></html>`,
            {status:200,headers:{...CORS,'Content-Type':'text/html'}});

        const {data:book} = await sb.from('books')
            .select('id,title,author,cover').eq('id',review.book_id).maybeSingle();

        const slug         = toSlugSimple(book?.title||'');
        const canonicalUrl = `${SITE}/book/${slug}#review-${rid}`;
        const imgFnUrl     = `${SUPABASE_URL}/functions/v1/og-card?rid=${rid}&mode=img`;

        if (mode==='img') {
            const imgPath = `reviews/${rid}.png`;
            // Check cache
            const {data:cached} = await sb.storage.from('og-images')
                .download(imgPath).catch(()=>({data:null}));
            if (cached) {
                return new Response(await cached.arrayBuffer(),{
                    headers:{...CORS,'Content-Type':'image/png','Cache-Control':'public,max-age=86400'}
                });
            }
            // Fetch cover server-side — keep raw bytes for imagescript compositing
            let coverBytes: Uint8Array | null = null;
            if (book?.cover) {
                const coverUrl = book.cover.startsWith('http')
                    ? book.cover
                    : `${SITE}${book.cover.startsWith('/')?'':'/'}${book.cover}`;
                try {
                    const r=await fetch(coverUrl);
                    if (r.ok) {
                        coverBytes = new Uint8Array(await r.arrayBuffer());
                        console.log('Cover loaded:', coverUrl, coverBytes.byteLength, 'bytes');
                    } else {
                        console.warn('Cover fetch failed:', r.status, coverUrl);
                    }
                } catch(e){ console.warn('Cover error:', e.message); }
            }
            // Step 1: Render SVG (text + layout only, no cover image)
            await init();
            const svg   = buildSvg(review, book, null);
            const resvg = new Resvg(svg, {
                fitTo: {mode:'width', value:1200},
                font:  fontBuffers.length>0
                    ? {fontBuffers, loadSystemFonts:false}
                    : {loadSystemFonts:true}
            });
            let png: Uint8Array = resvg.render().asPng();

            // Step 2: Composite cover onto left panel using imagescript
            if (coverBytes) {
                try {
                    const { Image } = await import('https://deno.land/x/imagescript@1.2.15/mod.ts');
                    const coverImg = await Image.decode(coverBytes);
                    // Scale to fill 400×630, crop center
                    const scale = Math.max(400 / coverImg.width, 630 / coverImg.height);
                    coverImg.resize(Math.round(coverImg.width * scale), Math.round(coverImg.height * scale));
                    const cx = Math.max(0, Math.round((coverImg.width  - 400) / 2));
                    const cy = Math.max(0, Math.round((coverImg.height - 630) / 2));
                    const cropped = coverImg.crop(cx, cy, 400, 630);
                    const baseImg = await Image.decode(png);
                    baseImg.composite(cropped, 0, 0);
                    png = await baseImg.encode(1); // PNG
                    console.log('Cover composited onto card');
                } catch(compErr) {
                    console.warn('Cover compositing failed:', compErr.message);
                }
            }
            // Cache
            await sb.storage.from('og-images').upload(imgPath,png,
                {contentType:'image/png',upsert:true}).catch(e=>console.warn('cache:',e.message));
            return new Response(png,{
                headers:{...CORS,'Content-Type':'image/png','Cache-Control':'public,max-age=86400'}
            });
        }

        // HTML mode — use JSON serialization to guarantee UTF-8 strings
        const rawTitle = book?.title || 'Book';
        const rawUser  = review.username || '';
        const rawText  = review.text || '';
        const ogTitle  = `${rawTitle} — Reader Review | Acer Books`;
        const ogDesc   = `${rawUser} reviewed "${rawTitle}": ${rawText.substring(0,200)}`;
        const stars=review.rating?'★'.repeat(review.rating)+'☆'.repeat(5-review.rating)+'  ':'';
        const html=`<!DOCTYPE html><html lang="en"><head>
<meta charset="UTF-8"><title>${htmlEnt(ogTitle)}</title>
<meta property="og:type" content="article">
<meta property="og:url" content="${esc(canonicalUrl)}">
<meta property="og:title" content="${htmlEnt(ogTitle)}">
<meta property="og:description" content="${htmlEnt(stars+ogDesc)}">
<meta property="og:image" content="${esc(imgFnUrl)}">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:site_name" content="Acer Books">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${htmlEnt(ogTitle)}">
<meta name="twitter:description" content="${htmlEnt(stars+ogDesc)}">
<meta name="twitter:image" content="${esc(imgFnUrl)}">
<link rel="canonical" href="${esc(canonicalUrl)}">
<meta http-equiv="refresh" content="0;url=${esc(canonicalUrl)}">
</head><body><p>Loading&hellip; <a href="${esc(canonicalUrl)}">Click here</a></p>
<script>window.location.replace('${canonicalUrl.replace(/'/g,"\\'")}');</script>
</body></html>`;
        return new Response(new TextEncoder().encode(html),{status:200,headers:{...CORS,
            'Content-Type':'text/html;charset=utf-8',
            'Cache-Control':'public,max-age=3600,stale-while-revalidate=86400'}});
    } catch(err) {
        console.error('og-card fatal:',err);
        return new Response(String(err),{status:500,headers:CORS});
    }
});